// Shape the Error Trigger payload into an error_log row.
const data = $input.first().json;
const execution = data.execution || {};
const error = execution.error || {};

return [{
  json: {
    workflow: (data.workflow && data.workflow.name) || 'unknown',
    node: execution.lastNodeExecuted || (error.node && error.node.name) || null,
    level: 'fatal',
    message: String(error.message || 'unknown error').slice(0, 2000),
    payload: {
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      stack: String(error.stack || '').slice(0, 4000),
    },
  },
}];
